mapper.select:
select count(1)
from t_mq_send_failure current
where current.message_key = #{messageKey}
  and exists (
    select 1 from t_mq_send_failure earlier
    where earlier.ordering_key = #{orderingKey}
      and earlier.id < current.id
  )

mapper.update:
update t_mq_send_failure
set status = 1, locked_at = #{now}, update_time = #{now}
where id = #{id}
  and ((status = 0 and next_retry_time <= #{now})
    or (status = 1 and locked_at <= #{lockExpiredAt}))
